export type Result<T, E = string> =
  | { ok: true; value: T }
  | { ok: false; error: E };

export function ok<T>(value: T): Result<T, never> { return { ok: true, value }; }
export function err<E>(error: E): Result<never, E> { return { ok: false, error }; }

export function parseSeats(text: string): Result<number> {
  const n = Number(text);
  return Number.isInteger(n) && n > 0 ? ok(n) : err('bad seats: ' + text);
}

import { parseSeats } from '../src/result.ts';
const r = parseSeats('30');
const seats: number = r.ok ? r.value : 0; // r.value must be a number when ok
export { seats };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseSeats } from '../src/result.ts';

test('ok', () => { const r = parseSeats('30'); assert.equal(r.ok && r.value, 30); });
test('err', () => { const r = parseSeats('x'); assert.equal(r.ok, false); });

