export interface Box {
  readonly value: any;
  map(f: (value: any) => any): Box;
}

export class BoxValue implements Box {
  readonly value: any;
  constructor(value: any) { this.value = value; }
  map(f: (value: any) => any): Box { return new BoxValue(f(this.value)); }
}

import { BoxValue } from '../src/box.ts';
const n = new BoxValue(10);
const text = n.map((x) => 'n' + x);
const s: string = text.value;  // the mapped value is a string
export { s };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { BoxValue } from '../src/box.ts';

test('map', () => assert.equal(new BoxValue(10).map((x) => 'n' + x).value, 'n10'));

